$ErrorActionPreference='Stop';$b='C:\OttrinTreeUIQA';$r="$b\results";function Assert($v,$m){if(-not$v){throw $m}};. "$b\snapshot.ps1";$source="$env:USERPROFILE\TreeQA2\same-directory-unoccupied\s\bundle "+[char]0x3A9;$target="$env:USERPROFILE\TreeQA2\same-directory-unoccupied\d\bundle "+[char]0x3A9;$result=@{status='running';scope='Ordinary-user direct Directory.Move control after failed GUI operation and product teardown'};try{Assert ($env:USERNAME-eq'OttrinTreeUIQA') 'Wrong user';Assert (-not(Test-Path "$env:LOCALAPPDATA\Programs\Ottrin")) 'Product remains';Assert ((Test-Path -LiteralPath $source)-and-not(Test-Path -LiteralPath $target)) 'Unexpected control topology';$before=@(Snapshot $source);$result.before=$before;[IO.Directory]::Move($source,$target);$result.forward=$true;Assert (EqualSnapshot @(Snapshot $target) $before $true) 'Forward move altered tree';[IO.Directory]::Move($target,$source);$result.restored=$true;Assert (EqualSnapshot @(Snapshot $source) $before $true) 'Restore altered tree';$result.status='pass'}catch{$result.status='fail';$result.error=$_.Exception.Message;$result.hresult=$_.Exception.GetBaseException().HResult};$result|ConvertTo-Json -Depth 20|Set-Content "$r\DIRECT_CONTROL.json" -Encoding UTF8;if($result.status-ne'pass'){exit 1}